#!/bin/bash
# One pass: working Docker path + dead-artifact removal. No patch context to
# conflict on - files are written from embedded base64.
set -euo pipefail
REPO="${1:-$HOME/OpenIOCCollector}"
cd "$REPO"
echo "== writing files into $REPO =="
base64 -d > Dockerfile <<'B64'

B64
echo "   wrote Dockerfile"
base64 -d > .dockerignore <<'B64'

B64
echo "   wrote .dockerignore"
base64 -d > requirements.txt <<'B64'

B64
echo "   wrote requirements.txt"
base64 -d > docker-compose.yml <<'B64'

B64
echo "   wrote docker-compose.yml"
base64 -d > gitpush.sh <<'B64'

B64
echo "   wrote gitpush.sh"
base64 -d > README.md <<'B64'

B64
echo "   wrote README.md"
chmod +x gitpush.sh
echo "== removing dead artifacts =="
git rm -q --ignore-unmatch latest.json whitelist.py organize_output.py normalize.py
git rm -rq --ignore-unmatch site
echo "   removed latest.json site/ whitelist.py organize_output.py normalize.py"
echo "== checks =="
python3 -c "import yaml;d=yaml.safe_load(open('docker-compose.yml'));print('compose OK:',list(d['services']))"
bash -n gitpush.sh && echo "gitpush.sh syntax OK"
python3 -m unittest discover -s tests 2>&1 | tail -3
echo
git status --short
echo
echo "Then: git add -A && git commit -m \"Working Docker path; remove dead artifacts\" && git push"
